if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf_token']??null)){ $id=(int)post('withdrawal_id');$action=(string)post('action');$w=docArray(collection('withdrawals')->findOne(['id'=>$id,'status'=>'pending']));if($w){if($action==='approve'){collection('withdrawals')->updateOne(['id'=>$id],['$set'=>['status'=>'approved','reviewed_at'=>nowIso()]]);collection('transactions')->updateOne(['reference_id'=>$id,'type'=>'withdrawal'],['$set'=>['status'=>'completed']]);flash('success','Withdrawal approved.');}elseif($action==='reject'){collection('withdrawals')->updateOne(['id'=>$id],['$set'=>['status'=>'rejected','reviewed_at'=>nowIso()]]);collection('wallets')->updateOne(['user_id'=>(int)$w['user_id']],['$inc'=>['balance'=>(float)$w['amount'],'total_withdrawn'=>-(float)$w['amount']],'$set'=>['updated_at'=>nowIso()]]);collection('transactions')->updateOne(['reference_id'=>$id,'type'=>'withdrawal'],['$set'=>['status'=>'failed']]);flash('success','Withdrawal rejected and balance refunded.');}}redirect(appUrl('admin/withdrawals.php'));}
